package com.dawnrise.school.announcement;

import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.net.URI;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;

class SchoolNotificationPostgresTest {
 private NamedParameterJdbcTemplate jdbc;private DriverManagerDataSource data;
 @BeforeEach void setup(){String url=System.getenv("SCHOOL_NOTIFICATION_TEST_DATABASE_URL");Assumptions.assumeTrue(explicit(url));data=new DriverManagerDataSource(url,System.getenv().getOrDefault("SCHOOL_NOTIFICATION_TEST_DATABASE_USER","postgres"),System.getenv().getOrDefault("SCHOOL_NOTIFICATION_TEST_DATABASE_PASSWORD",""));Flyway.configure().dataSource(data).load().migrate();jdbc=new NamedParameterJdbcTemplate(data);jdbc.getJdbcTemplate().execute("TRUNCATE school_notification_outbox,dawnrise_release_audit,dawnrise_release_organizations,dawnrise_releases,school_announcement_audit,school_announcement_audiences,school_announcements,schools RESTART IDENTITY CASCADE");jdbc.getJdbcTemplate().update("INSERT INTO schools(id,school_code,name,email,phone,status) VALUES(1,'ONE','One','one@test.invalid','111','ACTIVE'),(2,'TWO','Two','two@test.invalid','222','ACTIVE')");}
 @Test void v10MigratesAndEnforcesTenantAudienceForeignKey(){jdbc.getJdbcTemplate().update("INSERT INTO school_announcements(id,organization_id,title,body,severity,status,created_by_user_id) VALUES(10,1,'Title','Body','NORMAL','DRAFT',5)");assertThrows(Exception.class,()->jdbc.getJdbcTemplate().update("INSERT INTO school_announcement_audiences(organization_id,announcement_id,audience_type) VALUES(2,10,'WHOLE_SCHOOL')"));}
 @Test void claimIsExclusiveAndLeaseCanBeRecovered(){jdbc.getJdbcTemplate().update("INSERT INTO school_announcements(id,organization_id,title,body,severity,status,published_at,created_by_user_id) VALUES(10,1,'Title','Body','NORMAL','PUBLISHED',CURRENT_TIMESTAMP,5)");jdbc.getJdbcTemplate().update("INSERT INTO school_notification_outbox(source_type,source_id,organization_id,source_event_id,event_type,importance,heading,context,audience_spec,available_at) VALUES('ANNOUNCEMENT',10,1,'a:10','SCHOOL_ANNOUNCEMENT','NORMAL','Title','Open Dawnrise','[]',CURRENT_TIMESTAMP)");var store=new SchoolNotificationOutboxStore(jdbc);UUID first=UUID.randomUUID();assertTrue(store.claim(first,Duration.ofSeconds(1)).isPresent());assertTrue(store.claim(UUID.randomUUID(),Duration.ofSeconds(1)).isEmpty());jdbc.getJdbcTemplate().update("UPDATE school_notification_outbox SET lease_until=CURRENT_TIMESTAMP-INTERVAL '1 second'");assertTrue(store.claim(UUID.randomUUID(),Duration.ofSeconds(1)).isPresent());}
 @Test void expiredSourceCannotBeClaimed(){jdbc.getJdbcTemplate().update("INSERT INTO school_announcements(id,organization_id,title,body,severity,status,published_at,expires_at,created_by_user_id) VALUES(10,1,'Title','Body','NORMAL','PUBLISHED',CURRENT_TIMESTAMP-INTERVAL '2 hour',CURRENT_TIMESTAMP-INTERVAL '1 hour',5)");jdbc.getJdbcTemplate().update("INSERT INTO school_notification_outbox(source_type,source_id,organization_id,source_event_id,event_type,importance,heading,context,audience_spec,available_at) VALUES('ANNOUNCEMENT',10,1,'a:10','SCHOOL_ANNOUNCEMENT','NORMAL','Title','Open Dawnrise','[]',CURRENT_TIMESTAMP)");assertTrue(new SchoolNotificationOutboxStore(jdbc).claim(UUID.randomUUID(),Duration.ofMinutes(1)).isEmpty());}
 @Test void releaseTargetsAreDeduplicatedPerOrganization(){jdbc.getJdbcTemplate().update("INSERT INTO dawnrise_releases(id,title,summary,details,status,created_by_platform_user_id) VALUES(10,'Release','Summary','Details','DRAFT',7)");jdbc.getJdbcTemplate().update("INSERT INTO dawnrise_release_organizations(release_id,organization_id) VALUES(10,1)");assertThrows(Exception.class,()->jdbc.getJdbcTemplate().update("INSERT INTO dawnrise_release_organizations(release_id,organization_id) VALUES(10,1)"));}
 private boolean explicit(String url){if(url==null||!url.startsWith("jdbc:postgresql://"))return false;try{URI u=URI.create(url.substring(5));return Set.of("127.0.0.1","localhost").contains(u.getHost())&&u.getPath().matches("/dawnrise_school_notification_test_[A-Za-z0-9_]+");}catch(Exception e){return false;}}
}
